def max_expression_value(expression):
    def evaluate(expr):
        stack = []
        i = 0
        while i < len(expr):
            if expr[i].isdigit():
                num = int(expr[i])
                i += 1
                while i < len(expr) and expr[i].isdigit():
                    num = num * 10 + int(expr[i])
                    i += 1
                stack.append(num)
            elif expr[i] == '+':
                stack.append('+')
                i += 1
            elif expr[i] == '*':
                stack.append('*')
                i += 1
            elif expr[i] == '(':
                j = i
                balance = 1
                while balance != 0:
                    j += 1
                    if expr[j] == '(':
                        balance += 1
                    elif expr[j] == ')':
                        balance -= 1
                sub_expr = evaluate(expr[i+1:j])
                stack.append(sub_expr)
                i = j + 1

        result = stack[0]
        i = 1
        while i < len(stack):
            if stack[i] == '+':
                result += stack[i+1]
            elif stack[i] == '*':
                result *= stack[i+1]
            i += 2
        return result

    max_value = float('-inf')
    n = len(expression)

    for i in range(1, n-1, 2):
        left = expression[:i]
        right = expression[i+1:]
        value = evaluate(f"({left}){expression[i]}({right})")
        max_value = max(max_value, value)

    return max_value

